CREATE OR REPLACE VIEW lr_serverless_aws_us_catalog.bricksurance_semantics.financial_position
COMMENT 'Financial-statement line items assembled from the ledger via the statement mapping - the balance sheet and income statement in business language, by legal entity and regime. Query MEASURE(line_amount) grouped by statement and line; constrain currency_code and reporting_regime.'
WITH METRICS
LANGUAGE YAML
AS $$
version: 0.1

source: lr_serverless_aws_us_catalog.bricksurance_finance.journal_line

joins:
  - name: statement_line
    source: lr_serverless_aws_us_catalog.bricksurance_finance.statement_line
    on: source.account_id = statement_line.account_id
  - name: journal
    source: lr_serverless_aws_us_catalog.bricksurance_finance.journal
    on: source.journal_id = journal.journal_id

dimensions:
  - name: statement_type
    expr: statement_line.statement_type_code
  - name: reporting_regime
    expr: statement_line.reporting_regime_code
  - name: line_label
    expr: statement_line.line_label
  - name: legal_entity_id
    expr: journal.legal_entity_id
  - name: currency_code
    expr: source.currency_code

measures:
